const supportedLanguages = ["fr", "en", "ar"];
let originalTextNodes = [];
let originalDocumentTitle = document.title;
let currentLanguage = "fr";

function getStoredLanguage() {
  try {
    return window.localStorage?.getItem("language") || "fr";
  } catch (error) {
    return "fr";
  }
}

function storeLanguage(lang) {
  try {
    window.localStorage?.setItem("language", lang);
  } catch (error) {
    // La traduction reste fonctionnelle même si le stockage local est indisponible.
  }
}

function normalizeText(value) {
  return value.replace(/\s+/g, " ").trim();
}

function withOriginalSpacing(original, translated) {
  const leading = original.match(/^\s*/)?.[0] || "";
  const trailing = original.match(/\s*$/)?.[0] || "";
  return `${leading}${translated}${trailing}`;
}

function resolveTextTranslation(dictionary, key) {
  if (dictionary[key]) return dictionary[key];

  const numberedTitle = key.match(/^(\d+(?:\.\d+)?)(\.\s+|\s+)(.+)$/);
  if (numberedTitle && dictionary[numberedTitle[3]]) {
    return `${numberedTitle[1]}${numberedTitle[2].startsWith(".") ? ". " : " "}${dictionary[numberedTitle[3]]}`;
  }

  const caption = key.match(/^Capture\s+(\d+)\s+—\s+(.+)$/);
  if (caption && dictionary[caption[2]]) {
    return `${dictionary["Capture"] || "Capture"} ${caption[1]} — ${dictionary[caption[2]]}`;
  }

  return null;
}

function collectTextNodes() {
  originalTextNodes = [];

  const walker = document.createTreeWalker(
    document.body,
    NodeFilter.SHOW_TEXT,
    {
      acceptNode(node) {
        const parent = node.parentElement;
        if (!parent) return NodeFilter.FILTER_REJECT;
        if (parent.closest("script, style, pre, code, textarea, [data-no-i18n]")) {
          return NodeFilter.FILTER_REJECT;
        }
        return normalizeText(node.nodeValue).length > 1
          ? NodeFilter.FILTER_ACCEPT
          : NodeFilter.FILTER_REJECT;
      }
    }
  );

  let node = walker.nextNode();
  while (node) {
    originalTextNodes.push({ node, original: node.nodeValue });
    node = walker.nextNode();
  }
}

function applyDataTranslations(lang) {
  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const data = element.getAttribute("data-i18n") || "";

    data.split(";").forEach((item) => {
      const trimmedItem = item.trim();
      if (!trimmedItem) return;

      const match = trimmedItem.match(/^\[(.+)\](.+)$/);
      if (match) {
        const attr = match[1];
        const key = match[2];
        const originalAttrKey = `i18nOriginal${attr.replace(/[^a-z0-9]/gi, "")}`;

        if (!element.dataset[originalAttrKey]) {
          element.dataset[originalAttrKey] = element.getAttribute(attr) || "";
        }

        const translatedAttr = translations[lang]?.[key];
        element.setAttribute(attr, lang === "fr" ? element.dataset[originalAttrKey] : (translatedAttr || element.dataset[originalAttrKey]));
        return;
      }

      if (!element.dataset.i18nOriginalText) {
        element.dataset.i18nOriginalText = element.textContent || "";
      }

      const translatedText = translations[lang]?.[trimmedItem];
      element.textContent = lang === "fr"
        ? element.dataset.i18nOriginalText
        : (translatedText || element.dataset.i18nOriginalText);
    });
  });
}

function applyTextTranslations(lang) {
  const dictionary = textTranslations[lang] || {};

  originalTextNodes.forEach(({ node, original }) => {
    const key = normalizeText(original);
    const translated = resolveTextTranslation(dictionary, key);
    node.nodeValue = lang === "fr" ? original : (translated ? withOriginalSpacing(original, translated) : original);
  });
}

function translateText(value) {
  const text = normalizeText(String(value || ""));
  if (currentLanguage === "fr" || !text) return value;
  return resolveTextTranslation(textTranslations[currentLanguage] || {}, text) || value;
}

function setLanguage(lang) {
  const nextLanguage = supportedLanguages.includes(lang) ? lang : "fr";
  const isRtl = nextLanguage === "ar";
  currentLanguage = nextLanguage;

  applyDataTranslations(nextLanguage);
  applyTextTranslations(nextLanguage);
  document.title = nextLanguage === "fr"
    ? originalDocumentTitle
    : (resolveTextTranslation(textTranslations[nextLanguage] || {}, originalDocumentTitle) || originalDocumentTitle);

  document.documentElement.setAttribute("lang", nextLanguage);
  document.documentElement.setAttribute("dir", isRtl ? "rtl" : "ltr");
  document.body.setAttribute("dir", isRtl ? "rtl" : "ltr");
  document.body.classList.toggle("rtl", isRtl);

  storeLanguage(nextLanguage);
}

document.addEventListener("DOMContentLoaded", () => {
  collectTextNodes();
  setLanguage(getStoredLanguage());
});

window.setLanguage = setLanguage;
window.translateText = translateText;
